$primary-color: #0a4685;
$accent-color: #2f78d6;
$text-color: #172033;
$border-color: #e2e8f0;

.bannerContainer {
    position: relative;
    width: 100%;
    min-height: 670px;
    color: #ffffff;
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    overflow: visible;
    isolation: isolate;
}

// ---- Clip wrapper: constrains bgLayer to banner bounds ----
.bgClip {
    position: absolute;
    inset: 0;
    overflow: hidden;
    z-index: -1;
    // Do NOT use transform here — it would re-parent fixed children
}

// ---- Animated background layer (Ken Burns) ----
.bgLayer {
    position: absolute;
    inset: -10%;
    background-image: url('../../../assets/images/ryan-le-8-hEg1OuFn8-unsplash.jpg');
    background-size: cover;
    background-position: center 48%;
    animation: heroBgMove 24s ease-in-out infinite alternate;
    will-change: transform;
}

@keyframes heroBgMove {
    0%   { transform: scale(1)    translate(0,     0); }
    25%  { transform: scale(1.06) translate(-1.5%, -1%); }
    50%  { transform: scale(1.04) translate(1.5%,  1.5%); }
    75%  { transform: scale(1.08) translate(-0.5%, 2%); }
    100% { transform: scale(1.05) translate(1%,   -0.5%); }
}

.overlay {
    position: absolute;
    inset: 0;
    z-index: 0;
    background:
        linear-gradient(180deg, rgba(4, 22, 38, 0.28) 0%, rgba(4, 22, 38, 0.18) 30%, rgba(4, 22, 38, 0.52) 100%),
        linear-gradient(90deg, rgba(4, 22, 38, 0.48) 0%, rgba(4, 22, 38, 0.18) 50%, rgba(4, 22, 38, 0.32) 100%);
    pointer-events: none;
    backdrop-filter: blur(0.7px);
}

.content {
    position: relative;
    z-index: 30;
    width: min(90%, 1280px);
    margin: 0 auto;
    display: grid;
    grid-template-areas:
        "copy info"
        "search info"
        "error info";
    grid-template-columns: minmax(0, 1.85fr) minmax(320px, 0.78fr);
    column-gap: clamp(42px, 7vw, 112px);
    row-gap: 22px;
    padding-top: 138px;
}

.heroCopy {
    grid-area: copy;
    max-width: 830px;
}

.headline {
    margin: 0;
    color: #ffffff;
    font-size: clamp(2.1rem, 3.7vw, 3.45rem);
    line-height: 1.08;
    font-weight: 820;
    letter-spacing: 0;
    text-shadow: 0 12px 34px rgba(0, 0, 0, 0.32);
    animation: heroSlideUp 0.62s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.subHeadline {
    margin: 18px 0 0;
    color: rgba(255, 255, 255, 0.93);
    font-size: 1.02rem;
    font-weight: 580;
    line-height: 1.5;
    text-shadow: 0 8px 22px rgba(0, 0, 0, 0.25);
    animation: heroSlideUp 0.62s cubic-bezier(0.22, 1, 0.36, 1) 0.14s both;
}

.searchBox {
    grid-area: search;
    position: relative;
    z-index: 40;
    display: grid;
    grid-template-columns: minmax(0, 1.5fr) minmax(220px, 0.9fr) 104px;
    min-height: 70px;
    width: 100%;
    max-width: 930px;
    overflow: visible;
    background: rgba(10, 27, 48, 0.44);
    border: 1px solid rgba(255, 255, 255, 0.24);
    animation: heroSlideUp 0.62s cubic-bezier(0.22, 1, 0.36, 1) 0.26s both;
    border-radius: 8px;
    box-shadow: 0 20px 48px rgba(6, 17, 33, 0.22);
    backdrop-filter: blur(2px);
    animation: heroReveal 0.72s ease 0.08s both;
    transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;

    &:hover,
    &:focus-within {
        transform: translateY(-2px);
        border-color: rgba(255, 255, 255, 0.36);
        box-shadow: 0 26px 58px rgba(6, 17, 33, 0.28);
    }
}

.inputGroup {
    position: relative;
    display: flex;
    align-items: center;
    min-width: 0;
    padding: 0 24px;
    transition: background-color 0.18s ease;

    &:hover {
        background-color: rgba(255, 255, 255, 0.08);
    }

    &:not(:last-of-type) {
        border-right: 1px solid rgba(255, 255, 255, 0.15);
    }
}

.destinationGroup,
.budgetGroup {
    min-width: 0;
}

.icon {
    flex-shrink: 0;
    margin-right: 16px;
    color: rgba(255, 255, 255, 0.94);
}

.inputLabels {
    width: 100%;
    min-width: 0;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 5px;

    label {
        color: #ffffff;
        font-size: 0.88rem;
        font-weight: 760;
        line-height: 1.2;
    }
}

.inputField,
.selectDisplay {
    width: 100%;
    min-width: 0;
    padding: 0;
    border: none;
    outline: none;
    background: transparent;
    color: rgba(255, 255, 255, 0.96);
    font-size: 0.98rem;
    font-weight: 520;
    line-height: 1.35;
    cursor: pointer;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;

    &::placeholder {
        color: rgba(255, 255, 255, 0.62);
        font-weight: 460;
    }
}

.inputField {
    cursor: text;
}

.selectDisplay.placeholder {
    color: rgba(255, 255, 255, 0.62);
    font-weight: 460;
}

.customSelectMenu {
    position: absolute;
    top: calc(100% + 12px);
    left: 0;
    z-index: 100;
    width: min(280px, 100%);
    padding: 10px;
    background: rgba(255, 255, 255, 0.98);
    border: 1px solid $border-color;
    border-radius: 8px;
    box-shadow: 0 26px 60px rgba(15, 23, 42, 0.24);
    backdrop-filter: blur(10px);
}

.menuItem {
    padding: 11px 12px;
    margin-bottom: 5px;
    cursor: pointer;
    color: $text-color;
    font-weight: 650;
    border: 1px solid transparent;
    border-radius: 7px;
    transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;

    &:last-child {
        margin-bottom: 0;
    }

    &:hover {
        color: $primary-color;
        background-color: #eff6ff;
        border-color: #bfdbfe;
    }
}

.searchButton {
    width: 104px;
    height: 100%;
    align-self: stretch;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #ffffff;
    border: none;
    border-radius: 0 8px 8px 0;
    cursor: pointer;
    background: linear-gradient(135deg, #38bdf8, #2563eb);
    box-shadow: inset 1px 0 rgba(255, 255, 255, 0.12);
    transition: transform 0.18s ease, filter 0.18s ease, box-shadow 0.18s ease;

    &:hover {
        filter: brightness(1.08);
        box-shadow: inset 1px 0 rgba(255, 255, 255, 0.14), 0 12px 28px rgba(37, 99, 235, 0.2);
    }

    &:active {
        transform: scale(0.985);
    }
}

.searchIcon {
    flex-shrink: 0;
}

.validationMessage {
    grid-area: error;
    width: fit-content;
    max-width: 360px;
    margin: 0;
    padding: 10px 14px;
    color: #ffffff;
    background: rgba(220, 38, 38, 0.72);
    border: 1px solid rgba(255, 255, 255, 0.22);
    border-radius: 8px;
    box-shadow: 0 12px 28px rgba(0, 0, 0, 0.18);
}

// ============================================================
// 🌀 3D COVERFLOW GALLERY
// ============================================================

.sideInfoBox { display: none; }

// ---- Gallery wrapper ----
.galleryBox {
    grid-area: info;
    align-self: center;
    justify-self: end;
    width: min(100%, 430px);
    margin-top: 20px;
    padding: 0;
    border-radius: 0;
    background: transparent;
    border: none;
    overflow: visible;
    position: relative;
    animation: heroSlideUp 0.65s cubic-bezier(0.22, 1, 0.36, 1) 0.38s both;
}

// ---- 3D stage (horizontal coverflow) ----
.coverflow {
    position: relative;
    width: 100%;
    height: 300px;
    perspective: 900px;
    perspective-origin: center 50%;
    transform-style: preserve-3d;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: visible;
}

// ---- Each photo card ----
.coverCard {
    position: absolute;
    width: 78%;
    height: 244px;
    border-radius: 12px;
    overflow: hidden;
    cursor: pointer;
    will-change: transform, opacity, filter;
    backface-visibility: hidden;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.45);

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
        pointer-events: none;
        user-select: none;
        filter: blur(1.6px);
        transition: filter 0.35s ease;
    }
}

// Ken Burns zoom on active card — box-shadow glow (no transform conflict)
.coverCardActive {
    animation: activeGlow 3s ease-in-out infinite alternate;
    box-shadow: 0 20px 60px rgba(14, 165, 233, 0.45);
}

.coverCardActive img {
    filter: blur(0);
    animation: kenBurns 7s ease-in-out infinite alternate;
}

@keyframes activeGlow {
    from { box-shadow: 0 16px 48px rgba(0, 0, 0, 0.5); }
    to   { box-shadow: 0 24px 64px rgba(14, 165, 233, 0.55); }
}

@keyframes floatUp {
    from { transform: translateY(0px) rotateX(0deg) scale(1.0); }
    to   { transform: translateY(-8px) rotateX(0deg) scale(1.0); }
}

@keyframes kenBurns {
    from { transform: scale(1)    translate(0, 0); }
    to   { transform: scale(1.08) translate(-1.5%, 1%); }
}

// ---- Dot indicators (hidden) ----
.galleryDots {
    display: none;
}

.galleryDot { display: none; }
.galleryDotActive { display: none; }


.gallerySlide {
    position: relative;
    width: 100%;
    height: 200px;
    overflow: hidden;
    background: #0a1a2e;
}

.galleryImg {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 5s ease;

    &:hover {
        transform: scale(1.04);
    }
}

// Slide-in (from right or left)
.slideIn {
    animation: slideInFromRight 0.42s cubic-bezier(0.32, 0.76, 0.5, 1) both;
}

.slideOutLeft {
    animation: slideOutToLeft 0.42s cubic-bezier(0.32, 0.76, 0.5, 1) both;
}

.slideOutRight {
    animation: slideOutToRight 0.42s cubic-bezier(0.32, 0.76, 0.5, 1) both;
}

@keyframes slideInFromRight {
    from { opacity: 0; transform: translateX(32px) scale(0.97); }
    to   { opacity: 1; transform: translateX(0)     scale(1); }
}
@keyframes slideOutToLeft {
    from { opacity: 1; transform: translateX(0); }
    to   { opacity: 0; transform: translateX(-24px); }
}
@keyframes slideOutToRight {
    from { opacity: 1; transform: translateX(0); }
    to   { opacity: 0; transform: translateX(24px); }
}

// gradient overlay on photo
.galleryOverlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg,
        rgba(4, 16, 32, 0.06) 0%,
        rgba(4, 16, 32, 0.44) 100%
    );
    pointer-events: none;
    z-index: 2;
}

// Badge top-left
.galleryBadge {
    position: absolute;
    top: 10px;
    left: 10px;
    z-index: 4;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 4px 9px;
    background: rgba(37, 99, 235, 0.82);
    border: 1px solid rgba(255, 255, 255, 0.25);
    border-radius: 999px;
    color: #fff;
    font-size: 0.72rem;
    font-weight: 700;
    backdrop-filter: blur(4px);
    letter-spacing: 0.02em;
}

// Location bottom-left
.galleryLocation {
    position: absolute;
    bottom: 10px;
    left: 10px;
    z-index: 4;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 4px 9px;
    background: rgba(4, 12, 28, 0.72);
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 999px;
    color: #fff;
    font-size: 0.72rem;
    font-weight: 700;
    backdrop-filter: blur(4px);
}

// Prev / Next nav buttons
.galleryNav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    z-index: 5;
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(6, 18, 36, 0.64);
    border: 1px solid rgba(255, 255, 255, 0.22);
    border-radius: 50%;
    color: #fff;
    cursor: pointer;
    transition: background 0.18s ease, transform 0.18s ease;

    &:hover {
        background: rgba(37, 99, 235, 0.82);
        transform: translateY(-50%) scale(1.12);
    }
}

.galleryNavPrev { left: 8px; }
.galleryNavNext { right: 8px; }

// ---- Thumbnail strip ----
.galleryThumbs {
    display: flex;
    gap: 6px;
    padding: 10px 10px 6px;
    overflow-x: auto;
    scrollbar-width: none;

    &::-webkit-scrollbar { display: none; }
}

.galleryThumb {
    flex-shrink: 0;
    position: relative;
    width: 52px;
    height: 38px;
    border-radius: 6px;
    overflow: hidden;
    border: 2px solid transparent;
    cursor: pointer;
    padding: 0;
    background: none;
    transition: border-color 0.2s ease, transform 0.2s ease;

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
        transition: transform 0.35s ease;
    }

    &:hover img {
        transform: scale(1.1);
    }
}

.galleryThumbActive {
    border-color: #38bdf8;
    transform: translateY(-2px);
    box-shadow: 0 6px 16px rgba(56, 189, 248, 0.4);
}

// Ripple effect on thumb hover
.galleryThumbRipple {
    position: absolute;
    inset: 0;
    background: radial-gradient(circle at center,
        rgba(56, 189, 248, 0.32) 0%,
        transparent 70%
    );
    opacity: 0;
    transition: opacity 0.22s ease;
    pointer-events: none;

    .galleryThumb:hover & {
        opacity: 1;
    }
}

// ---- Dot indicators ----
.galleryDots {
    display: flex;
    justify-content: center;
    gap: 6px;
    padding: 6px 0 12px;
}

.galleryDot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.35);
    cursor: pointer;
    transition: background 0.22s ease, transform 0.22s ease, width 0.22s ease;
    display: inline-block;

    &:hover {
        background: rgba(255, 255, 255, 0.7);
    }
}

.galleryDotActive {
    width: 20px;
    border-radius: 4px;
    background: #38bdf8;
    transform: none;
}

.featuredBadge,
.featuredText {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    margin: 0 0 18px;
    color: #fde68a;
    font-size: 1.02rem;
    font-weight: 820;
    letter-spacing: 0;
}

.sideTitle {
    margin: 0 0 8px;
    color: #ffffff;
    font-size: 1.18rem;
    line-height: 1.35;
    font-weight: 800;
}

.sideDetails {
    margin: 0;
    color: rgba(255, 255, 255, 0.9);
    font-size: 0.92rem;
    font-weight: 560;
}

.priceLabel {
    margin: 24px 0 6px;
    color: rgba(255, 255, 255, 0.8);
    font-size: 0.83rem;
    font-weight: 620;
}

.priceRow {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
}

.priceValue {
    margin: 0;
    color: #fbbf24;
    font-size: clamp(1.6rem, 2.3vw, 2.05rem);
    line-height: 1.05;
    font-weight: 860;
    letter-spacing: 0;

    small {
        display: block;
        margin-top: 8px;
        color: #ffffff;
        font-size: 0.76rem;
        font-weight: 560;
        white-space: nowrap;
    }
}

.arrowIcon {
    flex: 0 0 56px;
    width: 56px;
    height: 56px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: #ffffff;
    border: none;
    border-radius: 14px;
    cursor: pointer;
    background: linear-gradient(135deg, #60a5fa, #2563eb);
    box-shadow: 0 16px 30px rgba(37, 99, 235, 0.24);
    transition: transform 0.18s ease, filter 0.18s ease, box-shadow 0.18s ease;

    &:hover {
        filter: brightness(1.08);
        transform: translateX(2px) translateY(-1px);
        box-shadow: 0 18px 34px rgba(37, 99, 235, 0.3);
    }
}

.bottomInfoStrip {
    position: absolute;
    left: 50%;
    bottom: -52px;
    z-index: 14;
    transform: translateX(-50%);
    width: min(90%, 1040px);
    display: flex;
    justify-content: space-around;
    padding: 20px 0;
    background: rgba(255, 255, 255, 0.97);
    border: 1px solid rgba(226, 232, 240, 0.9);
    border-radius: 8px;
    box-shadow: 0 22px 46px rgba(15, 23, 42, 0.11);
    backdrop-filter: blur(10px);
    animation: floatUp 0.66s ease 0.2s both;
}

.infoItem {
    flex: 1;
    min-width: 0;
    padding: 0 22px;
    text-align: center;
    color: $text-color;
    border-right: 1px solid #e5eaf0;
    transition: transform 0.2s ease;

    &:hover {
        transform: translateY(-2px);
    }

    &:last-child {
        border-right: none;
    }

    p {
        margin: 2px 0;
        color: #1f2937;
        font-size: 0.9rem;
        line-height: 1.35;
    }

    strong {
        color: $primary-color;
        font-weight: 820;
    }
}

.infoIcon {
    width: 44px;
    height: 44px;
    margin: 0 auto 8px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 8px;
}

.infoIconPrimary {
    color: #0369a1;
    background: linear-gradient(135deg, #e0f2fe, #bae6fd);
}

.infoIconReview {
    color: #c2410c;
    background: linear-gradient(135deg, #ffedd5, #fed7aa);
}

.infoIconDeal {
    color: #0f766e;
    background: linear-gradient(135deg, #ccfbf1, #99f6e4);
}

.statusMessage,
.statusMessageError {
    position: absolute;
    left: 5%;
    bottom: 24px;
    z-index: 12;
    margin: 0;
}

.statusMessage {
    color: #ffffff;
}

.statusMessageError {
    color: #fecaca;
}

@keyframes heroReveal {
    from { opacity: 0; transform: translateY(16px); }
    to   { opacity: 1; transform: translateY(0); }
}

@keyframes heroSlideUp {
    from { opacity: 0; transform: translateY(32px); }
    to   { opacity: 1; transform: translateY(0); }
}

@keyframes floatUp {
    from {
        opacity: 0;
        transform: translate(-50%, 14px);
    }
    to {
        opacity: 1;
        transform: translate(-50%, 0);
    }
}

@media (prefers-reduced-motion: reduce) {
    .heroCopy,
    .searchBox,
    .sideInfoBox,
    .bottomInfoStrip {
        animation: none;
    }

    .searchBox,
    .sideInfoBox,
    .infoItem,
    .arrowIcon {
        transition: none;
    }
}

@media (max-width: 1024px) {
    .bannerContainer {
        min-height: 710px;
    }

    .content {
        grid-template-areas:
            "copy"
            "search"
            "info"
            "error";
        grid-template-columns: 1fr;
        padding-top: 116px;
    }

    .sideInfoBox {
        justify-self: start;
        align-self: start;
        width: min(100%, 520px);
    }

    .bottomInfoStrip {
        bottom: -62px;
        width: calc(100% - 36px);
    }
}

@media (max-width: 760px) {
    .bannerContainer {
        min-height: 790px;
        background-position: center top;
    }

    .content {
        width: calc(100% - 28px);
        padding-top: 96px;
        row-gap: 18px;
    }

    .headline {
        font-size: clamp(2rem, 10vw, 2.65rem);
    }

    .searchBox {
        grid-template-columns: 1fr;
        min-height: auto;
    }

    .inputGroup {
        min-height: 70px;
        border-right: none !important;
        border-bottom: 1px solid rgba(255, 255, 255, 0.16);
    }

    .searchButton {
        width: 100%;
        min-height: 62px;
        border-radius: 0 0 8px 8px;
    }

    .priceRow {
        align-items: flex-start;
    }

    .bottomInfoStrip {
        position: relative;
        left: auto;
        bottom: auto;
        transform: none;
        width: calc(100% - 28px);
        margin: 28px auto -36px;
        flex-direction: column;
        gap: 14px;
        padding: 18px;
        animation: none;
    }

    .infoItem {
        border-right: none;
        border-bottom: 1px solid #e5eaf0;
        padding: 0 0 14px;

        &:last-child {
            border-bottom: none;
            padding-bottom: 0;
        }
    }
}
