/* ── Verify Email (OTP) Page ─────────────────────────── */

@keyframes fadeIn   { from { opacity: 0; } to { opacity: 1; } }
@keyframes spin     { to { transform: rotate(360deg); } }
@keyframes shake    {
  0%, 100% { transform: translateX(0); }
  20%, 60% { transform: translateX(-6px); }
  40%, 80% { transform: translateX(6px); }
}
@keyframes blobFloat {
  0%, 100% { transform: translate(0, 0) scale(1); }
  50%      { transform: translate(15px, -15px) scale(1.05); }
}
@keyframes cardPop {
  from { opacity: 0; transform: scale(0.95) translateY(20px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}
@keyframes successBurst {
  0%   { transform: scale(0); opacity: 0; }
  50%  { transform: scale(1.15); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}

.page {
  margin-top: 30px;
  min-height: 100vh;
  width: 100%;
  background-image:
    linear-gradient(135deg, rgba(15, 23, 42, 0.55) 0%, rgba(30, 41, 59, 0.45) 100%),
    url('https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=1920&h=1080&fit=crop&q=80');
  background-size: cover;
  background-position: center;
  background-attachment: fixed;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 16px;
  position: relative;
  overflow: hidden;
  animation: fadeIn 0.4s ease;

  &::after {
    content: '';
    position: absolute;
    inset: 0;
    backdrop-filter: blur(4px);
    background: rgba(15, 23, 42, 0.15);
    pointer-events: none;
    z-index: 0;
  }
}

.bgShape1, .bgShape2 {
  position: absolute;
  border-radius: 50%;
  filter: blur(100px);
  opacity: 0.25;
  pointer-events: none;
  z-index: 0;
  animation: blobFloat 12s ease-in-out infinite;
}

.bgShape1 {
  width: 420px; height: 420px;
  top: -100px; right: -100px;
  background: radial-gradient(circle, #60a5fa, transparent 70%);
}

.bgShape2 {
  width: 380px; height: 380px;
  bottom: -100px; left: -100px;
  background: radial-gradient(circle, #818cf8, transparent 70%);
  animation-delay: -5s;
}

.card {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 480px;
  background: #fff;
  border-radius: 22px;
  padding: 32px 36px 28px;
  text-align: center;
  box-shadow:
    0 40px 100px rgba(0, 0, 0, 0.45),
    0 15px 40px rgba(0, 0, 0, 0.2);
  animation: cardPop 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);

  @media (max-width: 540px) {
    padding: 24px 22px;
  }
}

.header {
  margin-bottom: 24px;
}

.logo {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.logoIcon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: linear-gradient(135deg, #3b82f6, #2563eb);
  color: #fff;
  box-shadow: 0 6px 16px rgba(37, 99, 235, 0.4);
}

.logoText {
  font-size: 16px;
  font-weight: 800;
  letter-spacing: 0.5px;
  background: linear-gradient(135deg, #1e3a8a, #2563eb);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.iconBubble {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 64px;
  height: 64px;
  border-radius: 18px;
  background: linear-gradient(135deg, #eff6ff, #dbeafe);
  color: #2563eb;
  margin-bottom: 16px;
  box-shadow: 0 8px 20px rgba(37, 99, 235, 0.15);
}

.title {
  font-size: 24px;
  font-weight: 800;
  color: #0f172a;
  margin: 0 0 8px 0;
  letter-spacing: -0.3px;
}

.subtitle {
  font-size: 13.5px;
  color: #64748b;
  line-height: 1.6;
  margin: 0 0 24px 0;
}

.emailText {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #2563eb;
  font-weight: 700;
  font-size: 14px;
  margin-top: 4px;
}

/* OTP form */

.otpForm {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.otpRow {
  display: flex;
  justify-content: center;
  gap: 8px;

  @media (max-width: 420px) {
    gap: 5px;
  }
}

.otpBox {
  width: 50px;
  height: 60px;
  border: 2px solid #e2e8f0;
  border-radius: 12px;
  background: #f8fafc;
  font-size: 26px;
  font-weight: 800;
  color: #0f172a;
  text-align: center;
  font-family: 'Courier New', monospace;
  transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
  outline: none;
  caret-color: #2563eb;

  &:focus {
    border-color: #2563eb;
    background: #fff;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
    transform: translateY(-2px);
  }

  &:disabled {
    opacity: 0.6;
    cursor: not-allowed;
  }

  @media (max-width: 420px) {
    width: 44px;
    height: 54px;
    font-size: 22px;
  }
}

.otpFilled {
  border-color: #2563eb;
  background: #eff6ff;
  color: #1d4ed8;
}

.otpError {
  border-color: #fca5a5 !important;
  background: #fef2f2 !important;
  color: #dc2626 !important;
  animation: shake 0.4s ease;
}

.errorBox {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 14px;
  background: linear-gradient(135deg, #fef2f2, #fee2e2);
  border: 1px solid #fecaca;
  border-left: 3px solid #dc2626;
  border-radius: 10px;
  color: #b91c1c;
  font-size: 12.5px;
  font-weight: 500;
  animation: shake 0.4s ease;
}

.btnPrimary {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 100%;
  padding: 12px 16px;
  background: linear-gradient(135deg, #3b82f6, #1d4ed8);
  border: none;
  border-radius: 12px;
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
  box-shadow: 0 6px 18px rgba(37, 99, 235, 0.45);

  &:hover:not(:disabled) {
    background: linear-gradient(135deg, #2563eb, #1e40af);
    transform: translateY(-2px);
    box-shadow: 0 10px 24px rgba(37, 99, 235, 0.55);
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
    transform: none;
  }
}

.spinner {
  width: 14px;
  height: 14px;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-top-color: #fff;
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}

.spinning {
  animation: spin 1s linear infinite;
}

/* Resend */

.resendBox {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 18px;
  padding-top: 18px;
  border-top: 1px dashed #e2e8f0;
  font-size: 12.5px;
}

.resendLabel {
  color: #64748b;
}

.resendBtn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: none;
  border: none;
  color: #2563eb;
  font-weight: 700;
  font-size: 12.5px;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
  transition: all 0.2s ease;

  &:hover:not(:disabled) {
    background: #eff6ff;
    color: #1d4ed8;
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
}

.resendCooldown {
  color: #94a3b8;
  font-weight: 600;

  strong {
    color: #475569;
    font-family: 'Courier New', monospace;
  }
}

/* Help */

.helpBox {
  margin-top: 16px;
  padding: 10px 14px;
  background: #fffbeb;
  border: 1px solid #fde68a;
  border-radius: 10px;
  font-size: 12px;
  color: #78350f;
  line-height: 1.5;
  text-align: left;

  strong { color: #92400e; }
}

.footer {
  font-size: 12.5px;
  color: #64748b;
  margin: 16px 0 0 0;
}

.linkAccent {
  color: #2563eb;
  font-weight: 700;
  text-decoration: none;

  &:hover { color: #1d4ed8; text-decoration: underline; }
}

/* Success state */

.successBody {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  padding: 20px 0 8px;
}

.successIcon {
  color: #10b981;
  filter: drop-shadow(0 6px 20px rgba(16, 185, 129, 0.4));
  animation: successBurst 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.successTitle {
  font-size: 24px;
  font-weight: 800;
  color: #0f172a;
  margin: 0;
  letter-spacing: -0.3px;
}

.successText {
  font-size: 13.5px;
  color: #475569;
  line-height: 1.6;
  margin: 0 0 8px 0;
}
